/**
 * `motionary/design` (= `motionary/components/design`, 9.7) — design-tool
 * integration.
 *
 * - `figmaToMotion(reactions)` — Figma prototype reactions (plugin API
 *   `node.reactions`: ON_CLICK / ON_HOVER / ON_PRESS / AFTER_TIMEOUT with
 *   DISSOLVE / SMART_ANIMATE / MOVE_IN / SLIDE_IN / PUSH / SCROLL_ANIMATE
 *   transitions, easing and duration) → a Motionary DSL string for
 *   `data-motion`. The `figma-plugin/` scaffold in the repo uses it.
 * - `framerComponent(desc, { name })` — a Framer code component (React,
 *   property controls for every attribute) from the 8.9 component JSON.
 * - `motionToCss(rules, selector)` — CSS `@keyframes` + rules for the
 *   entrance rules of a motion string (timeline presets), for hand-off to
 *   teams without JS.
 * - `easingPoints(easing)` — the cubic-bezier control points of a CSS
 *   easing (named or `cubic-bezier(…)`), for spec sheets.
 */
import { parseMotion, serializeMotion, type MotionRule, type ComponentJSON } from '../dsl/index';
import { TIMELINE_PRESETS } from '../timeline/core';

const EASE: Record<string, [number, number, number, number]> = {
  linear: [0, 0, 1, 1],
  ease: [0.25, 0.1, 0.25, 1],
  'ease-in': [0.42, 0, 1, 1],
  'ease-out': [0, 0, 0.58, 1],
  'ease-in-out': [0.42, 0, 0.58, 1],
};
/** Control points [x1, y1, x2, y2] of a CSS easing (unknown → ease) (9.7). */
export function easingPoints(easing = 'ease'): [number, number, number, number] {
  const m = easing.match(/cubic-bezier\(\s*([-\d.]+)\s*,\s*([-\d.]+)\s*,\s*([-\d.]+)\s*,\s*([-\d.]+)\s*\)/);
  if (m) return [Number(m[1]), Number(m[2]), Number(m[3]), Number(m[4])];
  return EASE[easing] || EASE.ease;
}

const FIGMA_EASE: Record<string, string> = { LINEAR: 'linear', EASE_IN: 'ease-in', EASE_OUT: 'ease-out', EASE_IN_AND_OUT: 'ease-in-out', EASE_IN_BACK: 'cubic-bezier(0.36, 0, 0.66, -0.56)', EASE_OUT_BACK: 'spring', EASE_IN_AND_OUT_BACK: 'cubic-bezier(0.68, -0.6, 0.32, 1.6)', GENTLE: 'smooth', QUICK: 'ease-out', BOUNCY: 'spring', SLOW: 'ease-in-out' };
const FIGMA_TRIGGER: Record<string, string> = { ON_CLICK: 'click', ON_PRESS: 'click', ON_HOVER: 'hover', MOUSE_ENTER: 'hover', AFTER_TIMEOUT: 'load', ON_DRAG: 'click' };
const dirFx = (d: string | undefined, base: 'fade' | 'slide') => {
  const m: Record<string, string> = { LEFT: 'left', RIGHT: 'right', TOP: 'down', BOTTOM: 'up' };
  return base === 'fade' ? `fade-${m[d || 'BOTTOM'] || 'up'}` : `slide-${m[d || 'BOTTOM'] || 'up'}`;
};
/** Figma prototype reactions → a Motionary DSL string (unsupported reactions are skipped) (9.7). */
export function figmaToMotion(reactions: any[]): string {
  const rules: MotionRule[] = [];
  for (const r of reactions || []) {
    const trig = FIGMA_TRIGGER[r?.trigger?.type];
    const tr = r?.action?.transition ?? r?.actions?.[0]?.transition;
    if (!trig || !tr) continue;
    const effect = tr.type === 'DISSOLVE' ? 'fade' : tr.type === 'SMART_ANIMATE' || tr.type === 'SCROLL_ANIMATE' ? 'scale' : tr.type === 'MOVE_IN' || tr.type === 'PUSH' ? dirFx(tr.direction, 'fade') : tr.type === 'SLIDE_IN' ? dirFx(tr.direction, 'fade') : 'fade';
    const rule: MotionRule = { trigger: (r.trigger.type === 'AFTER_TIMEOUT' ? 'load' : trig) as MotionRule['trigger'], effect, options: {} };
    if (typeof tr.duration === 'number') rule.duration = Math.round(tr.duration * 1000);
    const e = tr.easing?.type ? FIGMA_EASE[tr.easing.type] : undefined;
    if (e) rule.easing = e === 'spring' ? 'cubic-bezier(0.34, 1.56, 0.64, 1)' : e === 'smooth' ? 'cubic-bezier(0.22, 1, 0.36, 1)' : e;
    if (tr.easing?.easingFunctionCubicBezier) {
      const b = tr.easing.easingFunctionCubicBezier;
      rule.easing = `cubic-bezier(${b.x1}, ${b.y1}, ${b.x2}, ${b.y2})`;
    }
    if (r.trigger.type === 'AFTER_TIMEOUT' && typeof r.trigger.timeout === 'number') rule.delay = Math.round(r.trigger.timeout * 1000);
    rules.push(rule);
  }
  return serializeMotion(rules);
}

const pascal = (s: string) => s.replace(/(^|[-_\s]+)([a-z0-9])/gi, (_, __, c) => c.toUpperCase()).replace(/[^A-Za-z0-9]/g, '') || 'Component';
/** A Framer code component (TSX source) for a component description (9.7). */
export function framerComponent(desc: ComponentJSON | string, opts: { name?: string } = {}): string {
  const d: ComponentJSON = typeof desc === 'string' ? JSON.parse(desc) : desc;
  const name = pascal(opts.name || d.tag.replace(/^usa-/, ''));
  const attrs = Object.entries(d.attrs || {}).filter(([k]) => /^[a-z][\w-]*$/.test(k));
  const prop = (k: string) => k.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  const controls = attrs.map(([k, v]) => `    ${prop(k)}: { type: ${!isNaN(Number(v)) && v !== '' ? 'ControlType.Number' : v === '' ? 'ControlType.Boolean' : 'ControlType.String'}, defaultValue: ${!isNaN(Number(v)) && v !== '' ? Number(v) : v === '' ? 'true' : JSON.stringify(v)} },`).join('\n');
  const jsxAttrs = attrs.map(([k]) => ` ${k === 'class' ? 'className' : k}={${v(prop(k))}}`).join('');
  function v(p: string) {
    return `props.${p}`;
  }
  const kids = (d.children || []).map((c) => (typeof c === 'string' ? c.replace(/[{}<>]/g, '') : '')).join(' ').trim();
  return `// Framer code component generated by motionary/design (9.7)\nimport { useEffect } from "react"\nimport { addPropertyControls, ControlType } from "framer"\nimport { defineWidgets } from "https://cdn.jsdelivr.net/npm/motionary/dist/components/widgets.js"\n\nexport default function ${name}(props) {\n    useEffect(() => defineWidgets(), [])\n    return <${d.tag}${jsxAttrs}>${kids}</${d.tag}>\n}\n\naddPropertyControls(${name}, {\n${controls}\n})\n`;
}

/** CSS `@keyframes` + rules for the entrance (`enter` / `load`) rules of a motion string (9.7). */
export function motionToCss(rules: string | MotionRule[], selector = '.motion'): string {
  const rs = typeof rules === 'string' ? parseMotion(rules).rules : rules;
  const out: string[] = [];
  const done = new Set<string>();
  for (const r of rs) {
    if (r.trigger !== 'enter' && r.trigger !== 'load') continue;
    const kf = TIMELINE_PRESETS[r.effect];
    if (!kf) continue;
    const name = `usa-${r.effect}`;
    if (!done.has(name)) {
      done.add(name);
      const steps = kf.map((f, i) => `  ${Math.round((f.offset != null ? Number(f.offset) : i / Math.max(1, kf.length - 1)) * 100)}% { ${Object.entries(f).filter(([k]) => k !== 'offset' && k !== 'easing').map(([k, val]) => `${k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)}: ${val}`).join('; ')} }`);
      out.push(`@keyframes ${name} {\n${steps.join('\n')}\n}`);
    }
    const target = r.stagger != null ? `${selector} > *` : selector;
    out.push(`${target} { animation: ${name} ${r.duration ?? 600}ms ${r.easing || 'cubic-bezier(0.22, 1, 0.36, 1)'} ${r.delay ?? 0}ms both; }`);
    if (r.stagger != null) for (let i = 2; i <= 8; i++) out.push(`${selector} > :nth-child(${i}) { animation-delay: ${(r.delay ?? 0) + r.stagger * (i - 1)}ms; }`);
  }
  out.push(`@media (prefers-reduced-motion: reduce) { ${selector}, ${selector} > * { animation: none !important; } }`);
  return out.join('\n');
}
